const assert = require('node:assert/strict');
require('./load-rules.cjs');
require('../src/engine.js');
const template = require('../src/workbook-template.json');
const E = global.OrderEngine;
const orders = E.parseOrders('JF30左右单开，2.8米高5.6米宽，客户：示例客户\n\nJF30单开，2.5米高7.2米宽，客户：示例客户', { date: '2026-10-18', mode: 'blank' });
const bytes = Buffer.from(E.buildXlsx(orders, template));
// The application's ZIP writer stores XML without compression; inspect the
// actual generated bytes, including checksums, instead of just its input rows.
function crc32(data) {
  let crc = 0xffffffff;
  for (const byte of data) {
    crc ^= byte;
    for (let i = 0; i < 8; i++) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0);
  }
  return (crc ^ 0xffffffff) >>> 0;
}
const files = new Map();
let offset = 0;
while (bytes.readUInt32LE(offset) === 0x04034b50) {
  assert.equal(bytes.readUInt16LE(offset + 8), 0, 'Stored ZIP entry');
  const size = bytes.readUInt32LE(offset + 18), nameSize = bytes.readUInt16LE(offset + 26), extraSize = bytes.readUInt16LE(offset + 28);
  const name = bytes.subarray(offset + 30, offset + 30 + nameSize).toString('utf8');
  const start = offset + 30 + nameSize + extraSize;
  const body = bytes.subarray(start, start + size);
  assert.equal(crc32(body), bytes.readUInt32LE(offset + 14), name + ' CRC32');
  files.set(name, body.toString('utf8'));
  offset = start + size;
}
assert.equal(bytes.readUInt32LE(offset), 0x02014b50);
assert.equal(bytes.readUInt32LE(bytes.length - 22), 0x06054b50);
assert.equal(bytes.readUInt16LE(bytes.length - 12), files.size);
assert.ok(files.has('[Content_Types].xml'));
assert.match(files.get('xl/workbook.xml'), /fullCalcOnLoad="1"/);
const production = files.get('xl/worksheets/sheet1.xml');
assert.match(production, /<mergeCell ref="A2:A3"\/>/);
assert.match(production, /<mergeCell ref="B2:B3"\/>/);
assert.match(production, /<c r="D2"[^>]*><f>[\s\S]*?<\/f><v>5\.6<\/v><\/c>/);
assert.match(production, /<c r="E2"[^>]*><f>[\s\S]*?<\/f><v>2\.8<\/v><\/c>/);
assert.match(production, /少5\.62公分/);
assert.match(production, /多6\.84公分/);
const details = files.get('xl/worksheets/sheet2.xml');
assert.equal((details.match(/<row /g) || []).length, 3);
assert.match(details, /<c r="G3"[^>]*><v>7\.2<\/v><\/c>/);
assert.match(details, /<c r="H3"[^>]*><v>2\.5<\/v><\/c>/);
assert.match(files.get('xl/worksheets/sheet3.xml'), /左右单开/);
console.log('XLSX byte export passed: ZIP checksums, 3 sheets, width/height, cached results, formulas and merged cells.');
